package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var s string
	fmt.Fscan(in, &n, &s)

	chars := []byte(s)
	removed := 0

	for c := byte('z'); c > 'a'; c-- {
		for {
			found := false
			for i := 0; i < len(chars); i++ {
				if chars[i] != c {
					continue
				}
				if (i > 0 && chars[i-1] == c-1) ||
					(i+1 < len(chars) && chars[i+1] == c-1) {
					chars = append(chars[:i], chars[i+1:]...)
					removed++
					found = true
					break
				}
			}
			if !found {
				break
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, removed)
}

